/* Offline cache.
 *
 * The whole game is a handful of static files plus one baked data file, so it
 * can simply be precached wholesale. The old cache is dropped on activate.
 *
 * The block below is generated by tools/bump_cache.py and re-generated by the
 * pre-commit hook, so the cache name tracks a hash of what is actually in
 * docs/. A hand-maintained version number only busts the cache if someone
 * remembers to bump it, and a hand-maintained asset list only works offline if
 * someone remembers to add the file - both of which had already gone wrong once.
 */

/* GENERATED-BEGIN tools/bump_cache.py */
var CACHE = 'historic-ink-26b9fde963';

var ASSETS = [
  './',
  './icon.svg',
  './index.html',
  './manifest.webmanifest',
  './css/app.css',
  './css/wordmark.css',
  './data/signatures.js',
  './fonts/OFL-PinyonScript.txt',
  './js/app.js',
  './js/geom.js',
  './js/grade.js',
  './js/ink.js',
  './js/pad.js',
  './js/store.js'
];
/* GENERATED-END */

self.addEventListener('install', function (e) {
  e.waitUntil(
    caches.open(CACHE)
      .then(function (c) { return c.addAll(ASSETS); })
      .then(function () { return self.skipWaiting(); })
  );
});

self.addEventListener('activate', function (e) {
  e.waitUntil(
    caches.keys().then(function (keys) {
      return Promise.all(keys.map(function (k) {
        return k === CACHE ? null : caches.delete(k);
      }));
    }).then(function () { return self.clients.claim(); })
  );
});

self.addEventListener('fetch', function (e) {
  if (e.request.method !== 'GET') return;
  e.respondWith(
    caches.match(e.request).then(function (hit) {
      if (hit) return hit;
      return fetch(e.request).then(function (res) {
        // Cache same-origin successes so a first visit that misses the
        // precache list still works offline afterwards.
        if (res && res.ok && res.type === 'basic') {
          var copy = res.clone();
          caches.open(CACHE).then(function (c) { c.put(e.request, copy); });
        }
        return res;
      }).catch(function () {
        return caches.match('./index.html');
      });
    })
  );
});
